class Solution {
public:
    unordered_map<int, int> parent;
    int find(int x) {
        if (!parent.count(x)) parent[x] = x;
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
    bool canTraverseAllPairs(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return true;
        for (int x : nums) if (x == 1) return false;
        for (int x : nums) {
            int val = x;
            for (int d = 2; d * d <= val; ++d) {
                if (val % d == 0) {
                    unite(x, d);
                    while (val % d == 0) val /= d;
                }
            }
            if (val > 1) unite(x, val);
        }
        int root = find(nums[0]);
        for (int x : nums) {
            if (find(x) != root) return false;
        }
        return true;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    private Map<Integer, Integer> parent = new HashMap<>();
    private int find(int x) {
        parent.putIfAbsent(x, x);
        if (parent.get(x) != x) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }
    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent.put(rx, ry);
    }
    public boolean canTraverseAllPairs(int[] nums) {
        int n = nums.length;
        if (n == 1) return true;
        for (int x : nums) if (x == 1) return false;
        for (int x : nums) {
            int val = x;
            for (int d = 2; d * d <= val; d++) {
                if (val % d == 0) {
                    union(x, d);
                    while (val % d == 0) val /= d;
                }
            }
            if (val > 1) union(x, val);
        }
        int root = find(nums[0]);
        for (int x : nums) {
            if (find(x) != root) return false;
        }
        return true;
    }
}

var canTraverseAllPairs = function(nums) {
    const n = nums.length;
    if (n === 1) return true;
    for (const x of nums) if (x === 1) return false;
    const parent = new Map();
    function find(x) {
        if (!parent.has(x)) parent.set(x, x);
        if (parent.get(x) !== x) {
            parent.set(x, find(parent.get(x)));
        }
        return parent.get(x);
    }
    function union(x, y) {
        const rx = find(x);
        const ry = find(y);
        if (rx !== ry) parent.set(rx, ry);
    }
    for (const x of nums) {
        let val = x;
        for (let d = 2; d * d <= val; d++) {
            if (val % d === 0) {
                union(x, d);
                while (val % d === 0) val = Math.floor(val / d);
            }
        }
        if (val > 1) union(x, val);
    }
    const root = find(nums[0]);
    for (const x of nums) {
        if (find(x) !== root) return false;
    }
    return true;
};
